/* Lithuanian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Jonas": "God is gracious — Hebrew Yohanan", "Ona": "grace — Hebrew Hannah", "Petras": "rock, stone — Greek petros", "Marija": "A beloved feminine name.", "Vytautas": "he who leads the people — Lithuanian vyti + tauta", "Dalia": "fate, destiny — Lithuanian", "Kazlauskas": "A very common surname; feminine forms Kazlauskiene (married), Kazlauskaite (unmarried).", "Jankauskas": "A classic -as surname.", "Petrauskas": "A classic -as surname.", "Stankevicius": "A classic -ius surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Jonas';
console.log(lookup(q));

